+		.properties		= _props,				\
+		.num_properties		= ARRAY_SIZE(_props),			\
+		.charge_behaviours	= _behaviours,				\
+		.charge_types		= _types,				\
+		.get_property		= lwmi_psy_ext_get_prop,		\
+		.set_property		= lwmi_psy_ext_set_prop,		\
+		.property_is_writeable	= lwmi_psy_prop_is_writeable,		\
+	}
