+			}
+			break; /* Return what we have, or AGAIN */
+		}
+		msgs[i++] = msg;
+	}
+
+	*count = i;
+	if (i > 0)
+		return BT_MESSAGE_ITERATOR_CLASS_NEXT_METHOD_STATUS_OK;
+	return BT_MESSAGE_ITERATOR_CLASS_NEXT_METHOD_STATUS_AGAIN;
