-		gfs2_glock_dq_uninit(&ghs[qx]);
+		if (ghs[qx].gh_gl)
+			gfs2_glock_dq_uninit(&ghs[qx]);
 	inode_unlock(&ip->i_inode);
 	kfree(ghs);
